#!/usr/bin/env python3
"""Patch 103: the admin batch upload dialog shows each file as a readable card (the table squeezed the file name and cut off the Load as column). Run from the repo root. Safe to run twice."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {}
MOD = {'frontend/src/components/enh/AdminBatchUpload.tsx': [('              <div className="overflow-x-auto">\n                <table className="w-full text-xs border-collapse">\n                  <thead><tr className="text-left text-gray-500"><th className="py-1 pr-2">File</th><th className="pr-2">Records</th><th className="pr-2">Source</th><th className="pr-2">Now</th><th>Load as</th></tr></thead>\n                  <tbody>\n                    {rows.map((r, i) => (\n                      <tr key={r.file} className="border-t border-gray-100 align-top">\n                        <td className="py-1.5 pr-2 break-all">{r.file.split(\'/\').pop()}{r.error && <div className="text-red-600">{r.error}</div>}</td>\n                        <td className="pr-2">{r.records}{r.invalid ? <div className="text-amber-700">{r.invalid} fail the SOP check</div> : null}</td>\n                        <td className="pr-2">\n                          <select value={r.chosen} onChange={e => { const s = sources.find(x => x.id === e.target.value); set(i, { chosen: e.target.value, mode: e.target.value ? (s?.status === \'approved\' ? \'reference\' : r.mode === \'skip\' ? \'draft\' : r.mode) : \'skip\' }) }} className="border border-gray-200 rounded px-1.5 py-1 bg-white max-w-[14rem]">\n                            <option value="">Skip this file</option>\n                            {[...r.candidates.map(c => c.id), ...sources.map(s => s.id)].filter((v, k, a) => a.indexOf(v) === k).map(id => <option key={id} value={id}>{sources.find(s => s.id === id)?.name}</option>)}\n                          </select>\n                          {!r.source_id && !r.chosen && <div className="text-amber-700">No clear match</div>}\n                          {!!r.saved_copies && r.chosen === r.source_id && <div className="text-gray-500">{r.saved_copies} saved before</div>}\n                        </td>\n                        <td className="pr-2">{r.chosen ? `${sources.find(s => s.id === r.chosen)?.status?.replace(/_/g, \' \') ?? \'\'}${r.chosen === r.source_id && r.existing_records ? `, ${r.existing_records} records` : \'\'}` : \'\'}</td>\n                        <td>\n                          <select value={r.mode} onChange={e => set(i, { mode: e.target.value as Row[\'mode\'] })} disabled={!r.chosen} className="border border-gray-200 rounded px-1.5 py-1 bg-white">\n                            <option value="reference">Save privately</option>\n                            <option value="draft" disabled={sources.find(s => s.id === r.chosen)?.status === \'approved\'}>Load as data</option>\n                            <option value="skip">Skip</option>\n                          </select>\n                        </td>\n                      </tr>\n                    ))}\n                  </tbody>\n                </table>\n              </div>\n', '              <div className="space-y-2">\n                {rows.map((r, i) => {\n                  const chosenSrc = sources.find(s => s.id === r.chosen)\n                  return (\n                    <div key={r.file} className="border border-gray-200 rounded-lg p-3 space-y-2">\n                      <div className="flex items-baseline justify-between gap-3">\n                        <span className="font-medium text-gray-900 break-all">{r.file.split(\'/\').pop()}</span>\n                        <span className="text-xs text-gray-500 shrink-0">{r.records} record{r.records === 1 ? \'\' : \'s\'}</span>\n                      </div>\n                      {r.error && <div className="text-xs text-red-600">{r.error}</div>}\n                      {!!r.invalid && <div className="text-xs text-amber-700">{r.invalid} fail the SOP check</div>}\n                      <div className="grid gap-2 sm:grid-cols-[minmax(0,1fr)_11rem]">\n                        <label className="block text-xs text-gray-500">Source\n                          <select value={r.chosen} onChange={e => { const s = sources.find(x => x.id === e.target.value); set(i, { chosen: e.target.value, mode: e.target.value ? (s?.status === \'approved\' ? \'reference\' : r.mode === \'skip\' ? \'draft\' : r.mode) : \'skip\' }) }} className="mt-0.5 w-full border border-gray-200 rounded px-2 py-1.5 bg-white text-sm text-gray-900">\n                            <option value="">Skip this file</option>\n                            {[...r.candidates.map(c => c.id), ...sources.map(s => s.id)].filter((v, k, a) => a.indexOf(v) === k).map(id => <option key={id} value={id}>{sources.find(s => s.id === id)?.name}</option>)}\n                          </select>\n                        </label>\n                        <label className="block text-xs text-gray-500">Load as\n                          <select value={r.mode} onChange={e => set(i, { mode: e.target.value as Row[\'mode\'] })} disabled={!r.chosen} className="mt-0.5 w-full border border-gray-200 rounded px-2 py-1.5 bg-white text-sm text-gray-900">\n                            <option value="reference">Save privately</option>\n                            <option value="draft" disabled={chosenSrc?.status === \'approved\'}>Load as data</option>\n                            <option value="skip">Skip</option>\n                          </select>\n                        </label>\n                      </div>\n                      <div className="text-xs text-gray-500">\n                        {!r.source_id && !r.chosen && <span className="text-amber-700">No clear match. Pick the source, or skip this file.</span>}\n                        {!!r.chosen && <span>Now: {chosenSrc?.status?.replace(/_/g, \' \') ?? \'\'}{r.chosen === r.source_id && r.existing_records ? `, ${r.existing_records} records` : \'\'}</span>}\n                        {!!r.saved_copies && r.chosen === r.source_id && <span> · {r.saved_copies} saved before</span>}\n                      </div>\n                    </div>\n                  )\n                })}\n              </div>\n'), ('<Modal open={open} onClose={close} title="Admin batch upload"', '<Modal open={open} onClose={close} size="lg" title="Admin batch upload"')]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
